// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;
    bytes32 constant PROPOSER_ROLE = keccak256("PROPOSER_ROLE");

    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }

    function testFuzz_property(address account) public {
        // this contract holds TIMELOCK_ADMIN_ROLE, the stored admin of PROPOSER_ROLE
        bool ok;
        try c.grantRole(PROPOSER_ROLE, account) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok && c.hasRole(PROPOSER_ROLE, account));
    }
}
